SELECT 'FLEXVALUE' key,
'ROW_ID~FLEX_VALUE_SET_ID~FLEX_VALUE_ID~FLEX_VALUE~ENABLED_FLAG~START_DATE_ACTIVE~END_DATE_ACTIVE~SUMMARY_FLAG~VALUE_CATEGORY~CREATION_DATE~CREATED_BY~LAST_UPDATE_DATE~LAST_UPDATED_BY~LAST_UPDATE_LOGIN~COMPILED_VALUE_ATTRIBUTES~PARENT_FLEX_VALUE_LOW~PARENT_FLEX_VALUE_HIGH~STRUCTURED_HIERARCHY_LEVEL~HIERARCHY_LEVEL~ATTRIBUTE1~ATTRIBUTE2~ATTRIBUTE3~ATTRIBUTE4~ATTRIBUTE5~ATTRIBUTE6~ATTRIBUTE7~ATTRIBUTE8~ATTRIBUTE9~ATTRIBUTE10~ATTRIBUTE11~ATTRIBUTE12~ATTRIBUTE13~ATTRIBUTE14~ATTRIBUTE15~ATTRIBUTE16~ATTRIBUTE17~ATTRIBUTE18~ATTRIBUTE19~ATTRIBUTE20~ATTRIBUTE21~ATTRIBUTE22~ATTRIBUTE23~ATTRIBUTE24~ATTRIBUTE25~ATTRIBUTE26~ATTRIBUTE27~ATTRIBUTE28~ATTRIBUTE29~ATTRIBUTE30~ATTRIBUTE31~ATTRIBUTE32~ATTRIBUTE33~ATTRIBUTE34~ATTRIBUTE35~ATTRIBUTE36~ATTRIBUTE37~ATTRIBUTE38~ATTRIBUTE39~ATTRIBUTE40~ATTRIBUTE41~ATTRIBUTE42~ATTRIBUTE43~ATTRIBUTE44~ATTRIBUTE45~ATTRIBUTE46~ATTRIBUTE47~ATTRIBUTE48~ATTRIBUTE49~ATTRIBUTE50' FLEXVALUE 
FROM DUAL
UNION ALL
SELECT 'FLEXVALUE' key,
ROW_ID||'|'||FLEX_VALUE_SET_ID||'|'||FLEX_VALUE_ID||'|'||FLEX_VALUE||'|'||ENABLED_FLAG||'|'||START_DATE_ACTIVE||'|'||END_DATE_ACTIVE||'|'||SUMMARY_FLAG||'|'||VALUE_CATEGORY||'|'||CREATION_DATE||'|'||CREATED_BY||'|'||LAST_UPDATE_DATE||'|'||LAST_UPDATED_BY||'|'||LAST_UPDATE_LOGIN||'|'||REPLACE(REPLACE(COMPILED_VALUE_ATTRIBUTES,CHR(10),''),CHR(13),'') ||'|'||PARENT_FLEX_VALUE_LOW||'|'||PARENT_FLEX_VALUE_HIGH||'|'||STRUCTURED_HIERARCHY_LEVEL||'|'||HIERARCHY_LEVEL||'|'||ATTRIBUTE1||'|'||ATTRIBUTE2||'|'||ATTRIBUTE3||'|'||ATTRIBUTE4||'|'||ATTRIBUTE5||'|'||ATTRIBUTE6||'|'||ATTRIBUTE7||'|'||ATTRIBUTE8||'|'||ATTRIBUTE9||'|'||ATTRIBUTE10||'|'||ATTRIBUTE11||'|'||ATTRIBUTE12||'|'||ATTRIBUTE13||'|'||ATTRIBUTE14||'|'||ATTRIBUTE15||'|'||ATTRIBUTE16||'|'||ATTRIBUTE17||'|'||ATTRIBUTE18||'|'||ATTRIBUTE19||'|'||ATTRIBUTE20||'|'||ATTRIBUTE21||'|'||ATTRIBUTE22||'|'||ATTRIBUTE23||'|'||ATTRIBUTE24||'|'||ATTRIBUTE25||'|'||ATTRIBUTE26||'|'||ATTRIBUTE27||'|'||ATTRIBUTE28||'|'||ATTRIBUTE29||'|'||ATTRIBUTE30||'|'||ATTRIBUTE31||'|'||ATTRIBUTE32||'|'||ATTRIBUTE33||'|'||ATTRIBUTE34||'|'||ATTRIBUTE35||'|'||ATTRIBUTE36||'|'||ATTRIBUTE37||'|'||ATTRIBUTE38||'|'||ATTRIBUTE39||'|'||ATTRIBUTE40||'|'||ATTRIBUTE41||'|'||ATTRIBUTE42||'|'||ATTRIBUTE43||'|'||ATTRIBUTE44||'|'||ATTRIBUTE45||'|'||ATTRIBUTE46||'|'||ATTRIBUTE47||'|'||ATTRIBUTE48||'|'||ATTRIBUTE49||'|'||ATTRIBUTE50 
FLEXVALUE
FROM  FND_FLEX_VALUES a
 where ((:P_FROM_DATE IS NOT NULL AND :P_TO_DATE IS NOT NULL AND a.last_update_date between :P_FROM_DATE AND :P_TO_DATE) or
			(:P_FROM_DATE IS NULL AND :P_TO_DATE IS NULL AND a.last_update_date > (SELECT MAX(ERH.processstart)
                                         FROM ess_request_history ERH
                                             ,ess_request_property ERP
                                        WHERE ERH.requestid = ERP.requestid
                                          AND ERH.definition = 'JobDefinition://oracle/apps/ess/custom/cclf/CCLF_DL_Flexvalues'
                                          AND ERH.executable_status = 'SUCCEEDED'
                                          AND ERP.name = 'submit.argument1'
                             	          AND ERP.value IS  NULL)))
ORDER BY 1 DESC